-- swm_person 人员登记表
ALTER TABLE swm_person
    ADD dept VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '部门' AFTER job_type;

ALTER TABLE swm_person
    ADD position VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '职务' AFTER dept;


#  ==================== 字典 ==============================
# 人员和职务字典



# 危险源管理  增加是否报警标记
ALTER TABLE swm_hazard_source
    ADD filter_identity_card TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '白名单人员（这里的人员不收到报警信号）' AFTER beacon_tag;
ALTER TABLE swm_hazard_source
    ADD filter_personnel TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '白名单人员（这里的人员不收到报警信号）' AFTER filter_identity_card;


-- 日考勤统计表实体类
ALTER TABLE swm_daily_attendance
    ADD pending_clock_out_compensate BOOLEAN NOT NULL DEFAULT FALSE COMMENT '当天该员工是否已经触发过补偿且未恢复，true = 已补卡' AFTER clock_out_date;

# 人员增加人员编码、年龄、.紧急联系人、紧急联系人手机号
ALTER TABLE swm_person
    ADD person_number VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '人员编码' AFTER name;
ALTER TABLE swm_person
    ADD age VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '年龄' AFTER person_number;
ALTER TABLE swm_person
    ADD urgent_person VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '紧急联系人' AFTER phone_number;
ALTER TABLE swm_person
    ADD urgent_phone_number VARCHAR(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '紧急联系人手机号' AFTER urgent_person;

# 三车间

# 增加脱帽报警时间间隔
ALTER TABLE swm_helmet_device_config
    ADD hat_off_alarm_interval VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '脱帽报警时间间隔' AFTER beacon_filter_name;